css:
.table{
    border-collapse: collapse;
    margin: 3px 0;
}

.print-format label {
    text-align: left;
}

.print-format .important .value {
    text-align: right;
    font-size:100%!important;
    display: contents;
    font-weight: 600;
}

.print-format .value {
    text-align: left;

}

.table-sr {
    display: none !important;
}


.print-format .table-bordered, .print-format .table-bordered > thead > tr > th, .print-format .table-bordered > tbody > tr > th, .print-format .table-bordered > tfoot > tr > th, .print-format .table-bordered > thead > tr > td, .print-format .table-bordered > tbody > tr > td, .print-format .table-bordered > tfoot > tr > td {
    border: none !important;
    text-align: left;
    padding:None!important;
}

.table > tbody > tr > td {
    line-height: 0.9 !important;
}

@media all {
  .print-format {
       max-width: 100%;
       font-family: Monospaced, sans-serif !important;
       font-size: 8.0pt!important;
}
     
  
}

.print-format * {
    color: #0D131A !important;
    font-weight: 600;
}

.print-format print-format-preview {
    display: content!important;

}


[data-fieldtype="Date"] .value { 
    text-align: left; 
    
}

[data-fieldtype="Currency"] .value { 
    text-align: right;
    font-weight: bold;

}

[data-fieldtype="Table"] { 
    display: content;
}

[data-fieldname="rounded_total"] { 
    text-align: right;
}

#out_right{
    text-align:right!important;
    padding:0!important;

}
#out_left{
    text-align:left!important;
    padding:0!important;
}

format_data:
[{"fieldname": "print_heading_template", "fieldtype": "Custom HTML", "options": "<div style="text-align: center;">
    <h4>
        <div>Customer Requisition</div>
        <small class="sub-heading">{{ doc.name }}</small>
    </h4>
</div>"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <style>
        body {
            font-family: Arial, sans-serif;
            font-size: 12px;
        }
        .left-text {
            text-align: center;
            margin-top: 10px;
            margin-bottom: 10px;
            font-size: 12px;
        }
        strong {
            font-size: 12px;
        }
    </style>
</head>
<body>
    <div class="left-text">
        <p><strong>Date:</strong> {{ doc.date }}</p>
    </div>
</body>
</html>
"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<html>
<head>
    <style>
        body {
            font-family: Arial, sans-serif;
            font-size: 12px;
        }
        table {
            width: 100%;
            font-size: 12px;
        }
        strong {
            font-size: 12px;
        }
    </style>
</head>
<body>
    <table>
        <tbody>
            {% for item in doc.items %}
            <tr class="no-border">
                <td><strong>Item Name:</strong> <span style="font-weight: normal;">{{ item.item_name }}</span></td>
            </tr>
            <tr class="no-border">
                <td><strong>MOD/BRD:</strong> <span style="font-weight: normal;">{{ item.vehicle_model }}</span></td>
            </tr>
            <tr class="no-border">
                <td><strong>Part No:</strong> <span style="font-weight: normal;">{{ item.part_number }}</span></td>
            </tr>
            <tr class="no-border">
                <td><strong>OEM No:</strong> <span style="font-weight: normal;">{{ item.oem_number }}</span></td>
            </tr>
            <tr class="no-border">
                <td><strong>BIN:</strong> <span style="font-weight: normal;">{{ item.bin_location }}</span>  
                    &nbsp;&nbsp; <strong>Qty Req:</strong> <span style="font-weight: normal;">{{ item.qty }}</span>
                </td>
            </tr>
            <tr class="no-border">
                <td style="padding-top: 3px; padding-bottom: 3px;"><hr style="margin: 5px 0;"></td> 
            </tr>
            {% endfor %}
        </tbody>
    </table>

</body>
</html>
"}]
